from pathlib import Path

root = Path("app/src/main/java/com/byso/halocardoverlay")
file = root / "DashboardAccessibilityService.kt"
s = file.read_text(encoding="utf-8")

def substitute(old: str, new: str, context: str) -> None:
    global s
    if old not in s:
        raise SystemExit(f"Expected v1.6 code missing for: {context}. Refusing an unverified patch.")
    s = s.replace(old, new, 1)

# Events generated by the floating overlay itself are not changes to the
# foreground browser page. They must never hide the calculator.
substitute(
    '''        if (pkg !in browsers) {
            checks?.post { setState(false, "Outside supported browser") }
            return
        }''',
    '''        if (pkg == packageName || pkg.isBlank()) return
        if (pkg !in browsers) {
            // Keyboard, notification and overlay events aren't navigations.
            // Hide when an actual foreground window changes to another app.
            if (event.eventType == AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED ||
                event.eventType == AccessibilityEvent.TYPE_WINDOWS_CHANGED) {
                checks?.post { setState(false, "Outside supported browser") }
            }
            return
        }''',
    "ignore overlay and transient system events",
)

# Firefox generates TYPE_WINDOWS_CHANGED for many UI updates including the
# appearance of an overlay window. Never turn off visibility just for that.
# The throttled background active-URL inspection below still executes.
substitute(
    '''            if (probablyTabs || event.eventType == AccessibilityEvent.TYPE_WINDOWS_CHANGED) {''',
    '''            if (probablyTabs && event.eventType != AccessibilityEvent.TYPE_WINDOWS_CHANGED) {''',
    "prevent Firefox window-change feedback loop",
)

file.write_text(s, encoding="utf-8")
gradle = Path("app/build.gradle.kts")
g = gradle.read_text(encoding="utf-8")
if 'versionCode = 7' not in g or 'versionName = "1.6"' not in g:
    raise SystemExit("Expected v1.6 version not found")
g = g.replace("versionCode = 7", "versionCode = 8", 1)
g = g.replace('versionName = "1.6"', 'versionName = "1.7"', 1)
gradle.write_text(g, encoding="utf-8")
print("Applied HaloCard v1.7 non-blinking Firefox overlay update.")
